SELECT define_provision($q$ICC_CITY_PLAN_2025@2026-07-01$q$, $q$def setback (lower-case glossary entry - resolves to boundary clearance text)$q$, 'DEFINITION', $q$Boundary clearance means the distance between a building or structure on premises and the boundary of the premises, measured from the part of the building or structure that is closest to the boundary, other than a part that is:
an architectural or ornamental attachment; or
a rainwater fitting.
Examples:
If the fascia of a building is the part of the building that is closest to the boundary, the boundary clearance is the distance between the outside of the fascia and the boundary.
If a point on the roof of a building is the part of the building that is closest to the boundary, the boundary clearance is the distance between that point on the roof and the boundary.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2 Administrative Definitions (Administrative definitions)$q$, NULL, $q$https://ipswich.isoplan.com.au/eplan/api/l/rev/203/30-Jun-2026/1 (definitions array, rendered in ePlan Schedule 1)$q$, NULL, NULL);
