SELECT define_provision($q$ICC_CITY_PLAN_2025@2026-07-01$q$, $q$def site cover$q$, 'DEFINITION', $q$Site cover, of development, means the portion of the site, expressed as a percentage, that will be covered by a building or structure, measured to its outermost projection, after the development is carried out, other than a building or structure, or part of a building or structure, that is:
