SELECT define_rule($q${"rule_id": "ICC.dh_ro2_1_front_setback_new_suburban", "instrument_version": "ICC_CITY_PLAN_2025@2026-07-01", "topic": "SETBACK.FRONTAGE", "title": "9.3.7.3 Table 9.3.7.3.1 (Benchmarks for Accepted Development Subject to Requirements), RO2.1(a) / AO2.1(a)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 3, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "IPSWICH"}, {"level": "PRECINCT", "precinct": "ICC:LOW_DENSITY_RESIDENTIAL/NEW_SUBURBAN"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_ro2_1_front_setback_new_suburban", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front boundary setback\", \"operator\": \">=\", \"value\": 3, \"unit\": \"m\", \"conditions\": [\"Lot in New Suburban precinct\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Dwelling house / dual occupancy (garage door separately: see dh_ro2_1_garage_door_setback_new_suburban)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Part 1, s1.5 Table 1.5.1 'QDC Alternative Provisions' lists 'Alternatives to QDC boundary clearance provisions' and 'Alternatives to QDC site cover provisions' -> 'Dwelling House and Dual Occupancy Code' (and 'Alternatives to QDC building height provisions' -> 'Building Height and Density Overlay'). The table does not pin-point individual ROs/AOs; the setback/site-cover outcomes of the code are treated as the alternative provisions. Text says 'in the New Suburban precinct' without naming a zone; New Suburban is a precinct of the Low Density Residential zone (7.3.1.2(2))."}$q$::jsonb);
