SELECT define_provision($q$ICC_CITY_PLAN_2025@2026-07-01$q$, $q$9.3.7.3 Table 9.3.7.3.2 (Benchmarks for Assessable Development), PO7.1 / AO7.1$q$, 'ACCEPTABLE_OUTCOME', $q$PO7.1
Fences are designed and constructed to:
provide visual interest within the streetscape;
be comprised of materials and colours that are compatible with adjacent buildings and landscaping;
allow for casual surveillance and engagement with public spaces; and
assist in highlighting entrances and paths.
AO7.1
For residential areas where fencing is provided:
road frontage fencing is a maximum of 1.2m high, or 1.8m high if greater than 30% transparent;
where adjoining a secondary road frontage that does not provide access, drainage reserve, recreation or open space, fencing is a maximum of 1.8m high, solid up to 1.5m, with 80% transparency from 1.5m to 1.8m (as shown in Diagram A); and
otherwise, perimeter fencing may be solid and a maximum of 1.8m high.
DIAGRAM A$q$, 'VERIFIED_VERBATIM', $q$ruleId 18741$q$, NULL, $q$Dwelling House and Dual Occupancy Code$q$, NULL, $q$https://ipswich.isoplan.com.au/eplan/rules/0/404/0/0/0/203 (JSON: https://ipswich.isoplan.com.au/eplan/api/l/r/404/0/false/30-Jun-2026/false)$q$, $q$Relevant to pool barrier fences on frontages. Diagram A not extracted.$q$, $q$dh_ao7_1_fencing_heights$q$);
SELECT define_rule($q${"rule_id": "ICC.dh_ao7_1_fencing_heights", "instrument_version": "ICC_CITY_PLAN_2025@2026-07-01", "topic": "OTHER", "title": "9.3.7.3 Table 9.3.7.3.2 (Benchmarks for Assessable Development), PO7.1 / AO7.1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "PO7.1\nFences are designed and constructed to:\nprovide visual interest within the streetscape;\nbe comprised of materials and colours that are compatible with adjacent buildings and landscaping;\nallow for casual surveillance and engagement with public spaces; and\nassist in highlighting entrances and paths.\nAO7.1\nFor residential areas where fencing is provided:\nroad frontage fencing is a maximum of 1.2m high, or 1.8m high if greater than 30% transparent;\nwhere adjoining a secondary road frontage that does not provide access, drainage reserve, recreation or open space, fencing is a maximum of 1.8m high, solid up to 1.5m, with 80% transparency from 1.5m to 1.8m (as shown in Diagram A); and\notherwise, perimeter fencing may be solid and a maximum of 1.8m high.\nDIAGRAM A", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "IPSWICH"}, {"level": "ZONE", "zone": "ICC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "ICC:LOW_MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "ICC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "ICC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "ICC:CHARACTER_RESIDENTIAL"}, {"level": "ZONE", "zone": "ICC:TOWNSHIP"}, {"level": "ZONE", "zone": "ICC:EMERGING_COMMUNITY"}, {"level": "ZONE", "zone": "ICC:RURAL"}], "subjects": ["ANY"], "sources": [{"key": "dh_ao7_1_fencing_heights", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"maximum fence height\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"road frontage: <=1.2m, or <=1.8m if >30% transparent\", \"secondary road frontage not providing access, or adjoining drainage reserve / recreation / open space: <=1.8m, solid to 1.5m, 80% transparent 1.5-1.8m\", \"otherwise perimeter fencing may be solid, <=1.8m\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'fencing (road frontage, secondary road frontage, perimeter)' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Version 1 also had this as ADSR RO7.1; Version 2 removed RO7.1 from Table 9.3.7.3.1, so it now applies only to code-assessable development."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$ICC.dh_ao7_1_fencing_heights@2026-07-01$q$;
