A waste storage area is provided for each Dwelling* to accommodate the permanent storage of 3 x 240-litre refuse bins in an area outside of the road boundary setback (in an area other than within the building frontage).
*Note: A separate waste storage area is required for the Primary and Secondary dwelling forming a Dwelling house, or for each dwelling in a Dual occupancy.$q$, 'VERIFIED_VERBATIM', $q$ruleId 35422$q$, NULL, $q$Dwelling House and Dual Occupancy Code$q$, NULL, $q$https://ipswich.isoplan.com.au/eplan/rules/0/404/0/0/0/203 (JSON: https://ipswich.isoplan.com.au/eplan/api/l/r/404/0/false/30-Jun-2026/false)$q$, $q$$q$, $q$dh_ro6_5_bin_storage_outside_road_setback$q$);
SELECT define_rule($q${"rule_id": "ICC.dh_ro6_5_bin_storage_outside_road_setback", "instrument_version": "ICC_CITY_PLAN_2025@2026-07-01", "topic": "OTHER", "title": "9.3.7.3 Table 9.3.7.3.1 (Benchmarks for Accepted Development Subject to Requirements), RO6.5", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "RO6.5\nA waste storage area is provided for each Dwelling* to accommodate the permanent storage of 3 x 240-litre refuse bins in an area outside of the road boundary setback (in an area other than within the building frontage).\n*Note: A separate waste storage area is required for the Primary and Secondary dwelling forming a Dwelling house, or for each dwelling in a Dual occupancy.", "extracted_value": null, "extracted_operator": "="}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "IPSWICH"}, {"level": "ZONE", "zone": "ICC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "ICC:LOW_MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "ICC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "ICC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "ICC:CHARACTER_RESIDENTIAL"}, {"level": "ZONE", "zone": "ICC:TOWNSHIP"}, {"level": "ZONE", "zone": "ICC:EMERGING_COMMUNITY"}, {"level": "ZONE", "zone": "ICC:RURAL"}], "subjects": ["ANY"], "sources": [{"key": "dh_ro6_5_bin_storage_outside_road_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"bin storage location\", \"operator\": \"=\", \"value\": null, \"unit\": null, \"conditions\": [\"outside the road boundary setback\", \"3 x 240L bins per dwelling\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'waste/bin storage area' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Minor; affects use of the front setback."}$q$::jsonb);
