INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$IPSWICH$q$, $q$ICC_CITY_PLAN_2025$q$, 'MEDIUM', $q$The DH code defers front/side setbacks to 'Queensland Development Code MP1.1, MP1.2 or MP1.3', which the Queensland Housing Code replaced on 1 Sept 2026. Confirm with Council or certifiers whether these references are read as the QHC (under the Acts Interpretation Act or transitional provisions), and whether Council plans an amendment to reference the QHC.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$IPSWICH$q$, $q$ICC_CITY_PLAN_2025$q$, 'MEDIUM', $q$Table 1.5.1 names the whole DH code as the alternative to QDC boundary clearance. Is that designation effective for limbs that simply say 'meet QDC MP1.1/1.2'? In substance only the New Suburban and Rural variations and RO2.3 differ from QDC.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$IPSWICH$q$, $q$ICC_CITY_PLAN_2025$q$, 'MEDIUM', $q$The DH code has no rear setback provision, so rear setbacks presumably follow QDC/QHC. For the Rural zone 'side boundary setbacks ... minimum of 20m', confirm whether Council also applies it to rear boundaries and to class 10a outbuildings (no exemption is stated).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$IPSWICH$q$, $q$ICC_CITY_PLAN_2025$q$, 'MEDIUM', $q$Site cover is 60% for 'Dwelling houses and Dual occupancies' regardless of lot size. QHC site cover varies by lot size; the scheme value would prevail as an alternative provision.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$IPSWICH$q$, $q$ICC_CITY_PLAN_2025$q$, 'MEDIUM', $q$Building height 9.5m (RO3.2.1): Table 1.5.1 names OV6, not the DH code, as the height alternative, so it is unclear whether 9.5m operates as a QDC alternative.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$IPSWICH$q$, $q$ICC_CITY_PLAN_2025$q$, 'MEDIUM', $q$No outbuilding-specific size, height or setback rule was found in the DH code or the residential zone codes. The same applies to pool setbacks, garage width relative to frontage, impervious area and landscaping (the zone codes contain only purpose and overall outcomes).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$IPSWICH$q$, $q$ICC_CITY_PLAN_2025$q$, 'MEDIUM', $q$Precincts (e.g. New Suburban) are shown on the Zone and Precinct map, so a lot's precinct must be found from mapping (not extracted). OV6 heights and the Character overlay Areas A-D (Figure 8.2.3.3.20.1) are maps or images and were not extracted.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$IPSWICH$q$, $q$ICC_CITY_PLAN_2025$q$, 'MEDIUM', $q$Ipswich has no 'Rural Residential' zone. The equivalents are the Large Lot and Suburban Large Lot precincts of the Low Density Residential zone (no separate DH code setbacks) and the Rural zone (10m front / 20m side).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$IPSWICH$q$, $q$ICC_CITY_PLAN_2025$q$, 'MEDIUM', $q$The Table 5.7.1 preamble applies to building work that 'does not meet the definition for minor building works'. How this applies to small class 10a structures needs confirmation.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$IPSWICH$q$, $q$ICC_CITY_PLAN_2025$q$, 'MEDIUM', $q$The glossary has an upper-case 'SETBACK' entry with its own definition and a lower-case 'setback' entry that resolves to the 'Boundary clearance' text. Both are quoted; which one governs is ambiguous.$q$);
